{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "The proposed general cap of $4.8m (20% of price) may be a commercial negotiation point, but it cannot apply indiscriminately."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Revise the general claims regime to use a tipping basket, related-claim aggregation and appropriate survival periods."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "General business warranties: negotiate 18–24 months, with a claim notified in time allowed to be pursued to final resolution."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title claims must not be subject to the general cap and 18-month limit."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud and deliberate concealment: no contractual exclusion or limitation."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room/public-record disclosure and constructive/imputed Buyer-knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject the proposed qualification for matters “discoverable” from the data room or public records."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make valid Bluefen consent and satisfaction/waiver of all attached conditions a Completion Condition."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment at or immediately before Completion from Seller proceeds, with funds-flow itemisation"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Put the $420,000 Completion bonuses and every related employment on-cost into Seller’s Completion liability/funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require evidence of cleared payment and an unconditional confirmatory assignment/waiver from Ironquay before Completion."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require an investigation/remediation package, specific indemnity and holdback for the privacy incident."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Obtain complete underlying documents for the supplier renewals, office lease and Mossvale before accepting the Seller’s characterisations."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Ring-fence fundamental, tax, IP, debt/leakage, privacy and specific-indemnity claims from the general limitations regime."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "A share register showing Seller as registered holder is helpful but not conclusive protection."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Ring-fence fundamental, tax, IP, debt/leakage, privacy and specific-indemnity claims from the general limitations regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

